{"file_text": "@page "/chat"
@using sv_2419a1fc59254bc6b9e49d0f3640f376.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(_threadOpen ? "thread-open" : "")">
        <MessageArea ChannelName="@_activeChannel?.Name"
                     ChannelDescription="@_activeChannel?.Description"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadReplies = [];
    private Message? _threadRootMessage;
    private Dictionary<int, int> _threadReplyCounts = new();

    private Channel? _activeChannel;
    private int _activeChannelId;
    private bool _threadOpen;
    private int _messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messageSkip = 0;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messageSkip = _messages.Count;

        await ChatService.MarkChannelReadAsync(channelId);
        await BuildThreadReplyCounts();

        CloseThreadSync();
    }

    private async Task LoadMoreMessages()
    {
        if (_activeChannel is null) return;

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
            await BuildThreadReplyCounts();
        }
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;

        var message = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(message);
        _messageSkip++;
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThreadSync()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _activeChannel is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] = _threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Optimistically update local state
        var message = _messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (message is not null)
        {
            var existing = message.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                message.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
            }
        }
    }

    private Task BuildThreadReplyCounts()
    {
        _threadReplyCounts.Clear();
        // Group messages that are replies to find thread starters
        var replyGroups = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replyGroups)
        {
            _threadReplyCounts[group.Key] = group.Count();
        }

        return Task.CompletedTask;
    }
}
